def main():
    if len(sys.argv) >= 2 and sys.argv[1] == "--demo":
        render_funnel(demo_spec()); return
    if len(sys.argv) < 2:
        print(__doc__); sys.exit(1)
    spec = json.load(open(sys.argv[1]))
    if "--outdir" in sys.argv:
        spec["outdir"] = sys.argv[sys.argv.index("--outdir") + 1]
    render_funnel(spec)


